[package]
name = "auth-context-rs"
version = "0.1.0"
edition = "2021"

[dependencies]
steel-rs = "0.1"
chromiumoxide = { version = "0.7", default-features = false, features = ["tokio-runtime"] }
async-tungstenite = { version = "0.27", features = ["tokio-native-tls"] }
tokio = { version = "1", features = ["macros", "rt-multi-thread"] }
futures = "0.3"
serde = { version = "1", features = ["derive"] }
dotenvy = "0.15"

{
  "name": "auth-context-ts",
  "version": "1.0.0",
  "description": "A starter project for reusing authentication across Steel sessions with Playwright",
  "main": "index.ts",
  "scripts": {
    "test": "echo \"Error: no test specified\" && exit 1",
    "start": "ts-node index.ts"
  },
  "keywords": [
    "steel",
    "playwright",
    "authentication",
    "session-reuse"
  ],
  "author": "",
  "license": "ISC",
  "dependencies": {
    "dotenv": "^16.4.5",
    "playwright": "^1.48.2",
    "steel-sdk": "^0.10",
    "typescript": "^5.6.3"
  },
  "devDependencies": {
    "@types/node": "^22.9.0",
    "ts-node": "^10.9.2"
  }
}

{
  "name": "restate-agent-ts",
  "version": "1.0.0",
  "description": "Durable browser research agent with Restate, Steel, and TypeScript",
  "main": "index.ts",
  "scripts": {
    "start": "tsx index.ts",
    "typecheck": "tsc --noEmit"
  },
  "keywords": [],
  "author": "",
  "license": "MIT",
  "dependencies": {
    "@restatedev/restate-sdk": "^1.15.1",
    "dotenv": "^16.4.5",
    "steel-sdk": "^0.18.0",
    "tsx": "^4.19.2",
    "typescript": "^5.6.3"
  },
  "devDependencies": {
    "@types/node": "^22.9.0"
  }
}

{
  "name": "mcp-ts",
  "version": "0.1.0",
  "description": "Expose a Steel cloud browser to any MCP client",
  "license": "MIT",
  "scripts": {
    "start": "ts-node index.ts"
  },
  "dependencies": {
    "@modelcontextprotocol/sdk": "^1.29.0",
    "dotenv": "^16.4.7",
    "playwright": "^1.50.0",
    "steel-sdk": "^0.16",
    "zod": "^4.4.3"
  },
  "devDependencies": {
    "@types/node": "^20.0.0",
